import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

import { stacksManagedKindsList } from './generated/api'
import type { ManagedKindApi } from './generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface managedKindsLogicValues {
    currentTeam: TeamType | TeamPublicType | null // teamLogic
    managedKinds: ManagedKindApi[] | null
    managedKindsLoading: boolean
    managedKindsFailed: boolean
    managedKindNames: Set<string> | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface managedKindsLogicActions {
    loadManagedKinds: () => {
        value: true
    }
    loadManagedKindsSuccess: (managedKinds: ManagedKindApi[]) => {
        managedKinds: ManagedKindApi[]
    }
    loadManagedKindsFailure: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface managedKindsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        managedKindNames: (managedKinds: ManagedKindApi[] | null) => Set<string> | null
    }
}

export type managedKindsLogicType = MakeLogicType<
    managedKindsLogicValues,
    managedKindsLogicActions,
    Record<string, any>,
    managedKindsLogicMeta
>

/**
 * Which kinds some stack in the current project manages, read once.
 * Switching project reloads the app, so one unkeyed logic holds the answer for the session.
 * It reads nothing on mount: `managedEntityLogic` starts the read only while the feature flag is on.
 * A listener, not a loader, so a failed read stays silent: the scene works without it and shows no banner.
 */
export const managedKindsLogic = kea<managedKindsLogicType>([
    path(['products', 'stacks', 'frontend', 'managedKindsLogic']),
    connect(() => ({ values: [teamLogic, ['currentTeam']] })),
    actions({
        loadManagedKinds: true,
        loadManagedKindsSuccess: (managedKinds: ManagedKindApi[]) => ({ managedKinds }),
        loadManagedKindsFailure: true,
    }),
    reducers({
        managedKinds: [
            null as ManagedKindApi[] | null,
            { loadManagedKindsSuccess: (_, { managedKinds }) => managedKinds },
        ],
        managedKindsLoading: [
            false,
            {
                loadManagedKinds: () => true,
                loadManagedKindsSuccess: () => false,
                loadManagedKindsFailure: () => false,
            },
        ],
        managedKindsFailed: [false, { loadManagedKinds: () => false, loadManagedKindsFailure: () => true }],
    }),
    selectors({
        managedKindNames: [
            (s) => [s.managedKinds],
            (managedKinds): Set<string> | null =>
                managedKinds === null ? null : new Set(managedKinds.map((row) => row.kind)),
        ],
    }),
    listeners(({ actions, values }) => ({
        loadManagedKinds: async () => {
            const projectId = values.currentTeam?.project_id
            if (!projectId) {
                actions.loadManagedKindsFailure()
                return
            }
            try {
                actions.loadManagedKindsSuccess((await stacksManagedKindsList(String(projectId))).results)
            } catch {
                actions.loadManagedKindsFailure()
            }
        },
    })),
])
